  str_n38_6_levelname = "ST2 - Salida",
  str_n38_7_levelname = "N5 - Longzhou",
  str_n38_8_levelname = "N6 - Tormenta",
  str_n38_9_levelname = "N7 - Desviación",
  str_n38_10_levelname = "N8 - Reliquia",
  str_n38_11_levelname = "N9 - Emboscada",
  str_n38_12_levelname = "N10 - Zhui Hu",
  str_n38_13_levelname = "ST3 - Regreso a Casa",
  str_n38_1_levelname_desc = "—",
  str_n38_2_levelname_desc = "Las reparaciones de Shadowind están casi completas, pero de repente caes víctima de un ataque inesperado. Sin embargo, lo que se interpone entre tú y la perdición segura es...",
  str_n38_3_levelname_desc = "Con el banquete a bordo del Shadowind en pleno apogeo, Dantang comienza a preocuparse por tu ausencia. Ella está completamente ajena al peligro que acecha en las entrañas del barco...",
  str_n38_4_levelname_desc = "Con la ayuda de Xuan Ji, continúas buscando el origen de las Bestias Mecánicas rebeldes. Aparte del almacén, parece que todas las farmacias en el pueblo portuario también son altamente sospechosas.",
  str_n38_5_levelname_desc = "Todos tienen sus propias razones para regresar a Longzhou lo más pronto posible, así que ¿quién podría ser el verdadero objetivo de esta siniestra trama?",
  str_n38_6_levelname_desc = "—",
  str_n38_7_levelname_desc = "Incluso en el vasto mar abierto, no hay escapatoria de las hordas de Eclipsites, a las que se les llama \"espíritus malvados\" en Longzhou.",
  str_n38_8_levelname_desc = "En una noche aullante y tormentosa, un rayo golpea el Shadowind y provoca una enorme explosión. A través del caos, sientes la presencia de un poder especial...",
  str_n38_9_levelname_desc = "A la mañana siguiente, finalmente se restaura la paz en el barco, pero las aguas se vuelven completamente desconocidas. Parece que el barco se desvió del rumbo durante el calvario de anoche.",
  str_n38_10_levelname_desc = "Desorientado, el Shadowind llega a un lugar donde innumerables barcos yacen hundidos en las aguas. Para escapar de su situación traicionera, Xuan Ji sacrifica la posesión más preciada de su secta; sin embargo, un nuevo peligro se avecina justo más allá de su vista...",
  str_n38_11_levelname_desc = "El ataque repentino tanto de piratas como de Bestias Mecánicas te toma desprevenido, pero Xuan Ji rápidamente elabora una nueva estrategia. Ella cree que incluso tú puedes contribuir en gran medida en la próxima batalla.",
  str_n38_12_levelname_desc = "Mientras la lucha continúa, parece que Xuan Ji ha descubierto la identidad del capitán pirata. Esa persona no es otro que...",
  str_n38_13_levelname_desc = "—",
  str_n38_1_name_desc_long = "Después de aceptar un trabajo del Lin Guild, llegas a Twin Pavilions Bay por primera vez y observas cómo el Shadowind, uno de sus enormes barcos mercantes, llega al puerto. Mu Yuebai, capitán del barco, anuncia que estará atracado durante las próximas dos semanas para realizar algunas reparaciones muy necesarias. Con ese fin, Dantang recomienda a un cierto artesano en Twin Pavilions Bay para el trabajo.",
  str_n38_2_name_desc_long = "Después de pasar dos semanas productivas en Twin Pavilions Bay, las reparaciones de Shadowind finalmente se completan y Dantang logra convencer a un enviado de Lumopolis para que asista al banquete de celebración. Sin embargo, antes de que puedas unirte a ellos, eres atacado por un grupo de feroces Bestias Mecánicas que aparecen repentinamente en la ciudad. En el último segundo, Xuan Ji aparece y te salva del peligro: ella es la artesana que Dantang mencionó anteriormente, así como la diseñadora original de estas bestias mecánicas.",
  str_n38_3_name_desc_long = "Durante el banquete, la cabina de Shadowind es invadida por varias Bestias Mecánicas. El gremio Lin desea retrasar la salida del barco después del ataque, pero Dantang teme que su misión termine en fracaso si no regresa al Reino Ji lo suficientemente pronto. Después de todos sus esfuerzos para persuadir a Lumopolis de enviar un enviado, retrasar el viaje solo resultaría en pérdidas inimaginables.",
  str_n38_4_name_desc_long = "Tú y Xuan Ji continúan buscando el origen de las Bestias Mecánicas. Mientras investigan una farmacia, te enfrentas a un luchador desconocido. Tras darte cuenta de que ambos lados están equivocados, descubres que tus oponentes son Zhong Xu, un exfuncionario de Longzhou, y Liqing, un médico de barco de la familia Lin. Al regresar al Shadowind, Dantang te insta a reemplazar al enviado de Lumopolis como el nuevo emisario de Astra hacia el este.",
  str_n38_5_name_desc_long = "Aceptas viajar a Longzhou como representante de Astra, con la esperanza de que los dos continentes puedan asegurar un futuro mejor para ellos mismos. Zhong Xu también revela sus razones para querer regresar rápidamente a Longzhou, así como sus razones para ser atacado. Bajo la presión de tantas personas diferentes, la familia Lin no tiene más remedio que dejar que Shadowind parta lo antes posible. Mientras tanto, Xuan Ji comienza sus propias preparaciones para el largo viaje que le espera.",
  str_n38_6_name_desc_long = "El día de la partida finalmente llega y todos han hecho amplios preparativos para el viaje. Cargado con suficiente comida y medicinas, el barco y su tripulación están listos para zarpar. Antes de irte, también envías cartas de despedida a Vice y Carleen explicando la situación.",
  str_n38_7_name_desc_long = "En alta mar, Xuan Ji se ofrece como voluntaria para servir como fuente de navegación del Shadowind, ya que se ha perdido el esfera armilar de la familia Lin. Durante tus conversaciones con ella y Dantang, aprendes mucho sobre Longzhou, la navegación en general y algunos de los problemas que enfrentan en el Reino de Ye. Zhong Xu menciona cosas sobre Fiendlings y Eclipsites en Longzhou, lo que te proporciona algunas nuevas perspectivas.",
  str_n38_8_name_desc_long = "Durante una noche tormentosa, un rayo atraviesa el cielo, golpeando al Shadowind y provocando una explosión en lo profundo del barco. Mientras todos trabajan juntos para apagar las llamas y reparar los daños, descubres lo que parece ser el origen del fuego. Sin embargo, en poco tiempo, todos quedan prácticamente envueltos en un mar de llamas.",
  str_n38_9_name_desc_long = "Para el segundo día, el clima había mejorado y todos los incendios habían sido extinguidos. Bajo el tratamiento médico de Liqing, pronto recuperas la conciencia y recuerdas la sensación de ser engullido por el fuego de anoche. Xuan Ji informa que el incidente de anoche hizo que el barco se desviara de su rumbo, y pronto son emboscados por un grupo de misteriosas criaturas marinas. El Shadowind y su tripulación escapan por poco y comienzan a rescatar lo que pueden después del ataque.",
  str_n38_10_name_desc_long = "El Shadowind llega a una parte peligrosa del océano, donde los restos de innumerables barcos adornan el fondo marino. Como último recurso para rescatar el barco y sus pasajeros, Xuan Ji decide usar la Llama Zhuyin, uno de los objetos más preciados de su secta. Es el poder que sentiste anoche, y fue causado por alguien que secretamente quitó su sello. De repente, un barco aparece a lo lejos, aparentemente en respuesta a la señal de socorro del Shadowind. Sin embargo, a medida que se acerca, te das cuenta de que el barco que se aproxima es en realidad ¡un barco pirata!",
  str_n38_11_name_desc_long = "Una horda de piratas comienza a atacar a la tripulación con enormes Bestias Mecánicas, así que tú y Xuan Ji deciden dividirse y atacar desde diferentes ángulos. Mientras ella repele a los piratas atacantes, tú liberas a Zhong Xu y Liqing de la jaula mecánica que los aprisionaba. Cuando Zhong Xu se sumerge en el corazón de la batalla, su fuerza imparable recuerda a todos su pasado como el Gran General del Imperio Zhao.",
  str_n38_12_name_desc_long = "Mientras busca los puntos débiles en sus Bestias Mecánicas, Xuan Ji hace un sorprendente descubrimiento: la líder de los piratas no es otra que Zhui Hu, una mujer que fue su superior en sus estudios. Inventora de estas poderosas máquinas, desde entonces ha recurrido al contrabando y la piratería para sobrevivir. Después de una larga y amarga batalla, la tripulación del Shadowind finalmente logra repeler a los piratas y sus monstruos mecanizados.",
  str_n38_13_name_desc_long = "El Shadowind finalmente llega a tierra en Longzhou. Dantang completa su misión, Zhong Xu y Liqing finalmente se reúnen con el Maestro del Gremio Lin, y Xuan Ji planea comenzar una nueva misión. Aunque parece que el polvo finalmente se ha asentado, una figura en las sombras se prepara secretamente para la tormenta que se avecina...",
  str_n38_hard_name_1 = "H1 - Remo de Barco",
  str_n38_hard_name_2 = "H2 - Velas Sombras",
  str_n38_hard_name_3 = "H3 - Mástil y Remo",
  str_n38_hard_name_4 = "H4 - Remos Volteados",
  str_n38_hard_desc_1 = "Arrecifes no marcados están ocultos en las aguas adelante. Reduce la velocidad para identificar tu ruta con cuidado.",
  str_n38_hard_desc_2 = "Un vendaval comienza a soplar en el mar. Aprieta rápidamente las cuerdas de las velas para estabilizar el barco.",
  str_n38_hard_desc_3 = "Una enorme ola se dirige hacia ti. Asegura rápidamente todas las instalaciones en la cubierta.",
  str_n38_hard_desc_4 = "Un acantilado empinado ha aparecido de repente en el lecho marino. Da la vuelta inmediatamente para no chocar contra él y dañar tu barco.",
  str_n38_0_levelname_EX = "Barco perdido en el mar (náufrago)",
  str_n38_1_levelname_EX = "EX1 - Olas Furiosas",
  str_n38_2_levelname_EX = "EX2 - Mares Tormentosos",
