  str_n38_1_levelname_EX1 = "EX1-1 - Olas furiosas: Remolino",
  str_n38_1_levelname_EX2 = "EX1-2 - Olas Furiosas: Contra las Rocas",
  str_n38_2_levelname_EX1 = "EX2-1 - Mares tormentosos: Corriente turbulenta",
  str_n38_2_levelname_EX2 = "EX2-2 - Mares Tormentosos: Oleada",
  str_n38_3_levelname_EX1 = "EX3-1 - Marea Hirviente: Torrente Impetuoso",
  str_n38_3_levelname_EX2 = "EX3-2 - Marea agitada: Aguas desesperadas",
  str_n38_3_levelname_EX3 = "EX3-3 - Marea agitada: Ilimitada",
  str_n38_premission_lock = "Bloqueado",
